create or replace function public.create_warehouse(p_name text,p_type text default 'finished',p_opening_balance numeric default 0) returns public.warehouses language plpgsql security definer set search_path=public as $$declare w public.warehouses;begin if auth.uid() is null or not public.current_user_has_permission('inventory.create') then raise exception 'غير مصرح بإضافة مخزن';end if;if nullif(btrim(p_name),'') is null then raise exception 'اسم المخزن مطلوب';end if;insert into public.warehouses(name,warehouse_type) values(btrim(p_name),coalesce(nullif(p_type,''),'finished')) returning * into w;return w;end;$$;
create or replace function public.create_stock_movement_draft(p_direction text,p_source_type text,p_product_id uuid,p_quantity numeric,p_unit_name text,p_from_warehouse_id uuid default null,p_to_warehouse_id uuid default null,p_cost_price numeric default 0,p_notes text default null) returns public.stock_movements language plpgsql security definer set search_path=public as $$declare m public.stock_movements;begin if auth.uid() is null or not public.current_user_has_permission('inventory.create') then raise exception 'غير مصرح بإنشاء حركة مخزن';end if;if p_direction not in('in','out','transfer') then raise exception 'نوع الحركة غير صحيح';end if;if p_quantity<=0 then raise exception 'الكمية يجب أن تكون أكبر من صفر';end if;if p_product_id is null then raise exception 'اختر المنتج';end if;if p_direction in('in','out') and p_from_warehouse_id is null and p_to_warehouse_id is null then raise exception 'اختر المخزن';end if;if p_direction='transfer' and (p_from_warehouse_id is null or p_to_warehouse_id is null or p_from_warehouse_id=p_to_warehouse_id) then raise exception 'اختر مخزنين مختلفين للتحويل';end if;insert into public.stock_movements(direction,source_type,from_warehouse_id,to_warehouse_id,notes,created_by) values(p_direction,coalesce(nullif(p_source_type,''),'manual'),p_from_warehouse_id,p_to_warehouse_id,p_notes,auth.uid()) returning * into m;insert into public.stock_movement_lines(movement_id,product_id,quantity,unit_name,cost_price,notes) values(m.id,p_product_id,p_quantity,p_unit_name,greatest(p_cost_price,0),p_notes);return m;end;$$;
create or replace function public.approve_stock_movement(p_movement_id uuid) returns public.stock_movements language plpgsql security definer set search_path=public as $$declare m public.stock_movements;it record;balance numeric;warehouse uuid;begin if auth.uid() is null or not public.current_user_has_permission('inventory.approve') then raise exception 'غير مصرح باعتماد حركة المخزون';end if;select * into m from public.stock_movements where id=p_movement_id for update;if m.id is null then raise exception 'الحركة غير موجودة';end if;if m.status<>'draft' then raise exception 'الحركة اعتمدت أو ألغيت سابقًا';end if;warehouse:=m.from_warehouse_id;if m.direction='out' or m.direction='transfer' then for it in select product_id,quantity from public.stock_movement_lines where movement_id=m.id loop select coalesce(sum(case when sm.direction='in' then sml.quantity when sm.direction='out' then -sml.quantity when sm.direction='transfer' and sm.to_warehouse_id=warehouse then sml.quantity when sm.direction='transfer' and sm.from_warehouse_id=warehouse then -sml.quantity else 0 end),0) into balance from public.stock_movement_lines sml join public.stock_movements sm on sm.id=sml.movement_id where sml.product_id=it.product_id and sm.status='approved' and (sm.from_warehouse_id=warehouse or sm.to_warehouse_id=warehouse);if balance<it.quantity then raise exception 'الرصيد المتاح لا يكفي للحركة';end if;end loop;end if;update public.stock_movements set status='approved',approved_by=auth.uid(),approved_at=now() where id=m.id returning * into m;return m;end;$$;
grant execute on function public.create_warehouse(text,text,numeric) to authenticated;grant execute on function public.create_stock_movement_draft(text,text,uuid,numeric,text,uuid,uuid,numeric,text) to authenticated;grant execute on function public.approve_stock_movement(uuid) to authenticated;
